-- 005: Python and SQL build the same chain. The vectors file is generated by
-- packages/contracts/scripts/make_vectors.py with the rfc8785 package; SQL must reproduce
-- every canonical string, content hash and chain hash in it.
begin;
\i supabase/tests/_helpers.sql

create temp table vectors as select :'vectors'::jsonb as v;

do $$
declare
  v        jsonb;
  item     jsonb;
  v_chain  uuid;
  v_prev   text;
  v_hash   text;
  r        record;
  i        integer := 0;
begin
  select vectors.v into v from vectors;
  assert jsonb_array_length(v -> 'jcs') >= 3, 'vectors file has jcs cases';

  for item in select * from jsonb_array_elements(v -> 'jcs') loop
    assert audit.jcs(item -> 'input') = (item ->> 'jcs'),
      format('jcs mismatch for %s: sql=%s python=%s', item ->> 'name', audit.jcs(item -> 'input'), item ->> 'jcs');
    assert audit.content_hash(item ->> 'jcs') = (item ->> 'content_hash'),
      format('content_hash mismatch for %s', item ->> 'name');
  end loop;

  -- Fold the chain by hand, then again through append_evidence on a chain with the vectors' id.
  v_prev := audit.genesis_hash();
  for item in select * from jsonb_array_elements(v -> 'chain' -> 'events') loop
    i := i + 1;
    v_hash := audit.chain_hash(v_prev, audit.content_hash(audit.jcs(item)));
    assert v_hash = (v -> 'chain' -> 'hashes' ->> (i - 1)), format('chain hash %s differs from python', i);
    v_prev := v_hash;
  end loop;

  v_chain := (v -> 'chain' ->> 'chain_id')::uuid;
  insert into audit.chains (id, label) values (v_chain, 'vectors');
  i := 0;
  for item in select * from jsonb_array_elements(v -> 'chain' -> 'events') loop
    i := i + 1;
    select * into r from audit.append_evidence(v_chain, item);
    assert r.hash = (v -> 'chain' -> 'hashes' ->> (i - 1)), format('append_evidence hash %s differs from python', i);
  end loop;
  select * into r from audit.verify_chain(v_chain);
  assert r.ok and r.checked = i, r.detail;
end
$$;

rollback;
